import type { inferRouterInputs, inferRouterOutputs } from "@trpc/server";
import { router } from "../trpc";
import account from "./account";
import admin from "./admin";
import pub from "./public";
// Generated by scripts/compose-layers.ts on every Nuxt config load — the
// `routers` map of every ACTIVE layer, flattened. Core layers (config.ts's
// `layers.core`) and feature layers (`layers.features`) are the same mechanism
// here: both flow through `activeLayerNames` in nuxt.config.ts, so neither
// needs a hand-written import in this file.
import { layerRouters } from "./.composition/layer-routers";

export const appRouter = router({
  account,
  public: pub,
  admin,
  // `teams` and `invites` arrive through here (@nuxfire/layer-teams), since
  // Fase 3 passo 2a so do `billing` and `stripe` (@nuxfire/layer-billing), and
  // since passo 3 so does `notifications` (@nuxfire/layer-notifications) —
  // each layer's `routers` map mounts them under those exact top-level keys.
  // The client-facing API shape is unchanged; only where the modules live is.
  //
  // `admin.plans` and `admin.notifications` are deliberately NOT here: they
  // moved into @nuxfire/layer-billing and @nuxfire/layer-notifications too, but
  // as named exports OUTSIDE those layers' `routers` maps, because they are
  // mounted under `admin`, not at the top level. See ./admin/index.ts and each
  // layer's server/trpc/router.ts.
  ...layerRouters,
});

export type AppRouter = typeof appRouter;
export type RouterInput = inferRouterInputs<AppRouter>;
export type RouterOutput = inferRouterOutputs<AppRouter>;
